        overlay: "https://images.unsplash.com/photo-1703100825618-5a4696824d3b?q=80&w=1828&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D",
        badge:   "IMAGE_ANNIVERSARY_LEARNBETA_LOGO_GLOW",
